<?php
require_once dirname(__DIR__) . '/app/bootstrap.php';
require_admin();
$errors=[]; $saved=false;
$defaults=['color_primary'=>'#245B45','color_background'=>'#F3F6F4','color_surface'=>'#FFFFFF','color_text'=>'#24332B','color_footer_bg'=>'#173F31','color_footer_text'=>'#FFFFFF','color_header_bg'=>'#173F31','color_header_text'=>'#FFFFFF','color_hero_bg'=>'#F3F6F4','color_hero_eyebrow'=>'#245B45','color_hero_title'=>'#173F31','color_hero_text'=>'#24332B'];
function cms_settings_strlen(string $value): int { return preg_match_all('/./us', $value, $m) !== false ? count($m[0]) : strlen($value); }
function settings_upload(string $field, string $kind, array &$errors): ?string {
    if (empty($_FILES[$field]) || ($_FILES[$field]['error'] ?? UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE) return null;
    $f=$_FILES[$field]; if (($f['error']??1)!==UPLOAD_ERR_OK || !is_uploaded_file($f['tmp_name']??'')) { $errors[]='Caricamento immagine non riuscito.'; return null; }
    if (($f['size']??0)>2097152) { $errors[]='Immagine superiore a 2 MB.'; return null; }
    $i=@getimagesize($f['tmp_name']); $m=$i['mime']??''; $map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];
    if (!$i || !isset($map[$m]) || ($kind==='favicon' && !in_array($m,['image/png','image/gif'],true))) { $errors[]='Formato immagine non supportato.'; return null; }
    $dir=dirname(__DIR__).'/uploads/images'; if (!is_dir($dir) && !mkdir($dir,0755,true)) { $errors[]='Cartella immagini non disponibile.'; return null; }
    $n=$kind.'-'.bin2hex(random_bytes(12)).'.'.$map[$m]; if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$n)) { $errors[]='Impossibile salvare l’immagine.'; return null; }
    return 'uploads/images/'.$n;
}
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); $name=trim((string)($_POST['site_name']??'')); $desc=trim((string)($_POST['site_description']??''));
    if($name==='' || cms_settings_strlen($name)>100) $errors[]='Il nome del sito è obbligatorio (massimo 100 caratteri).';
    if(cms_settings_strlen($desc)>240) $errors[]='Descrizione troppo lunga (massimo 240 caratteri).';
    if(cms_settings_strlen(trim((string)($_POST['hero_eyebrow_text']??'')))>100 || cms_settings_strlen(trim((string)($_POST['hero_title_text']??'')))>160) $errors[]='I testi iniziali superano la lunghezza consentita.';
    $colors=[]; foreach($defaults as $k=>$v){$c=strtoupper(trim((string)($_POST[$k]??''))); if(!preg_match('/^#[0-9A-F]{6}$/',$c))$errors[]='Uno o più codici colore non sono validi.'; $colors[$k]=$c;}
    $logo=settings_upload('site_logo','logo',$errors); $favicon=settings_upload('site_favicon','favicon',$errors);
    $homePageId=(int)($_POST['home_page_id']??0);
    if($homePageId>0 && cms_table_exists('pages')){$q=$pdo->prepare('SELECT id FROM '.cms_table('pages')." WHERE id=? AND status='published' AND deleted_at IS NULL");$q->execute([$homePageId]);if(!$q->fetch())$errors[]='La pagina scelta per la homepage non esiste o non è pubblicata.';}
    if(!$errors){cms_set_setting('home_page_id',(string)$homePageId);cms_set_setting('site_name',$name);cms_set_setting('site_description',$desc);cms_set_setting('hero_eyebrow_text',trim((string)($_POST['hero_eyebrow_text']??'')));cms_set_setting('hero_title_text',trim((string)($_POST['hero_title_text']??'')));foreach($colors as $k=>$v)cms_set_setting($k,$v);if($logo)cms_set_setting('site_logo',$logo);if($favicon)cms_set_setting('site_favicon',$favicon);$_SESSION['flash']='Impostazioni del sito salvate.';header('Location: settings.php');exit;}
}
$vals=[];foreach($defaults as $k=>$v)$vals[$k]=cms_setting($k,$v);
$homePages=cms_table_exists('pages')?$pdo->query("SELECT id,title FROM ".cms_table('pages')." WHERE status='published' AND deleted_at IS NULL ORDER BY title")->fetchAll():[];
$homePageId=(int)cms_setting('home_page_id','0');
$name=cms_setting('site_name','MercurioCMS');$desc=cms_setting('site_description','');$logo=cms_setting('site_logo','');$favicon=cms_setting('site_favicon','');$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Impostazioni - MercurioCMS</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><?php $adminActive='settings'; require __DIR__.'/_sidebar.php'; ?><main class="container"><h1>Impostazioni del sito</h1><p>Puoi modificare in qualsiasi momento le scelte effettuate durante la configurazione iniziale.</p><?php if($flash):?><p class="notice"><?=e($flash)?></p><?php endif;?><?php if($errors):?><div class="error"><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form class="panel settings-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Pagina iniziale</h2><label>Contenuto da mostrare nella homepage<select name="home_page_id"><option value="0">Homepage automatica: elenco delle pagine pubblicate</option><?php foreach($homePages as $hp):?><option value="<?=(int)$hp['id']?>" <?=((int)($_POST['home_page_id']??$homePageId)===(int)$hp['id'])?'selected':''?>><?=e($hp['title'])?></option><?php endforeach;?></select></label><p class="editor-help">Seleziona una pagina pubblicata per mostrarla direttamente all'apertura del sito. Puoi tornare in qualsiasi momento alla homepage automatica.</p><h2>Identità del sito</h2><label>Nome del sito<input name="site_name" maxlength="100" required value="<?=e($_POST['site_name']??$name)?>"></label><label>Descrizione breve<input name="site_description" maxlength="240" value="<?=e($_POST['site_description']??$desc)?>"></label><div class="cards"><div><label>Logo (max 2 MB)<input type="file" name="site_logo" accept="image/png,image/jpeg,image/webp,image/gif"></label><?php if($logo):?><img class="setup-preview" src="../<?=e($logo)?>" alt="Logo attuale"><?php endif;?></div><div><label>Favicon (PNG o GIF, max 2 MB)<input type="file" name="site_favicon" accept="image/png,image/gif"></label><?php if($favicon):?><img class="favicon-preview" src="../<?=e($favicon)?>" alt="Favicon attuale"><?php endif;?></div></div><h2>Testi della pagina iniziale</h2><p>Lascia vuoto un campo se non vuoi visualizzare quella scritta.</p><label>Scritta piccola<input name="hero_eyebrow_text" maxlength="100" value="<?=e($_POST['hero_eyebrow_text']??cms_setting('hero_eyebrow_text','Sito web'))?>" placeholder="Es. Il mio sito"></label><label>Titolo principale<input name="hero_title_text" maxlength="160" value="<?=e($_POST['hero_title_text']??cms_setting('hero_title_text','Benvenuto'))?>" placeholder="Es. Benvenuti"></label><h2>Colori</h2><div class="colors-layout"><div class="color-grid"><?php $groups=['Aspetto generale'=>['color_primary'=>'Colore principale (link e pulsanti)','color_background'=>'Sfondo generale del sito','color_surface'=>'Sfondo dei riquadri e contenuti','color_text'=>'Colore del testo'],'Intestazione e menu'=>['color_header_bg'=>'Sfondo intestazione','color_header_text'=>'Testi e menu intestazione'],'Pagina iniziale'=>['color_hero_bg'=>'Sfondo area introduttiva','color_hero_eyebrow'=>'Scritta piccola','color_hero_title'=>'Titolo principale','color_hero_text'=>'Descrizione introduttiva'],'Piè di pagina'=>['color_footer_bg'=>'Sfondo piè di pagina','color_footer_text'=>'Testo piè di pagina']];foreach($groups as $groupTitle=>$labels):?><fieldset class="color-section"><legend><?=e($groupTitle)?></legend><div class="color-grid"><?php foreach($labels as $k=>$label):?><label class="color-field"><span><?=e($label)?></span><input type="color" name="<?=e($k)?>" value="<?=e($_POST[$k]??$vals[$k])?>"><small><?=e($_POST[$k]??$vals[$k])?></small></label><?php endforeach;?></div></fieldset><?php endforeach;?></div><div class="color-previews"><div class="color-actions"><button type="button" class="secondary" id="reset-colors">Ripristina colori originali</button></div><div class="header-color-preview" id="header-color-preview" style="background:<?=e($vals['color_header_bg'])?>;color:<?=e($vals['color_header_text'])?>"><strong><?=e($name)?></strong><span>Home　 ·　 Menu di navigazione</span></div><p class="editor-help">L'anteprima mostra l'effetto dei due colori sull'intestazione del sito.</p><h3>Anteprima generale e piè di pagina</h3><div id="general-color-preview" style="padding:16px;border-radius:8px;background:<?=e($vals['color_background'])?>;color:<?=e($vals['color_text'])?>"><div style="padding:14px;border-radius:6px;background:<?=e($vals['color_surface'])?>"><strong>Riquadro di esempio</strong><p>Questo è un esempio del testo della pagina.</p><a id="general-link-preview" href="#" style="color:<?=e($vals['color_primary'])?>">Collegamento o pulsante</a></div><div id="footer-color-preview" style="margin-top:10px;padding:12px;border-radius:6px;background:<?=e($vals['color_footer_bg'])?>;color:<?=e($vals['color_footer_text'])?>">Esempio di piè di pagina</div></div><h3>Anteprima dei testi iniziali</h3><div class="hero-color-preview" id="hero-color-preview" style="background:<?=e($vals['color_hero_bg'])?>"><?php $eyebrowPreview=cms_setting('hero_eyebrow_text','Sito web'); $titlePreview=cms_setting('hero_title_text','Benvenuto'); ?><span id="settings-eyebrow-preview" style="color:<?=e($vals['color_hero_eyebrow'])?>" <?=trim($eyebrowPreview)===''?'hidden':''?>><?=e($eyebrowPreview)?></span><strong id="settings-title-preview" style="color:<?=e($vals['color_hero_title'])?>" <?=trim($titlePreview)===''?'hidden':''?>><?=e($titlePreview)?></strong><p style="color:<?=e($vals['color_hero_text'])?>"><?=e($desc ?: 'Descrizione del sito')?></p></div><p class="editor-help">Puoi personalizzare separatamente lo sfondo, la scritta piccola, il titolo e la descrizione della pagina iniziale.</p></div></div><div class="form-actions"><button type="submit">Salva impostazioni</button></div></form><script>document.querySelectorAll('input[name=hero_eyebrow_text],input[name=hero_title_text]').forEach(el=>el.addEventListener('input',()=>{const target=document.getElementById(el.name==='hero_eyebrow_text'?'settings-eyebrow-preview':'settings-title-preview');target.textContent=el.value;target.hidden=el.value.trim()==='';}));const originalColors={'color_primary':'#245B45','color_background':'#F3F6F4','color_surface':'#FFFFFF','color_text':'#24332B','color_footer_bg':'#173F31','color_footer_text':'#FFFFFF','color_header_bg':'#173F31','color_header_text':'#FFFFFF','color_hero_bg':'#F3F6F4','color_hero_eyebrow':'#245B45','color_hero_title':'#173F31','color_hero_text':'#24332B'};function updateColorPreview(){const v=Object.fromEntries([...document.querySelectorAll('input[type=color]')].map(el=>[el.name,el.value]));const header=document.getElementById('header-color-preview');header.style.background=v.color_header_bg;header.style.color=v.color_header_text;const hero=document.getElementById('hero-color-preview');hero.style.background=v.color_hero_bg;hero.querySelector('span').style.color=v.color_hero_eyebrow;hero.querySelector('strong').style.color=v.color_hero_title;hero.querySelector('p').style.color=v.color_hero_text;const general=document.getElementById('general-color-preview');general.style.background=v.color_background;general.style.color=v.color_text;general.firstElementChild.style.background=v.color_surface;document.getElementById('general-link-preview').style.color=v.color_primary;const footer=document.getElementById('footer-color-preview');footer.style.background=v.color_footer_bg;footer.style.color=v.color_footer_text;}document.querySelectorAll('input[type=color]').forEach(el=>el.addEventListener('input',()=>{const hex=el.parentElement.querySelector('small');if(hex)hex.textContent=el.value.toUpperCase();updateColorPreview();}));document.getElementById('reset-colors')?.addEventListener('click',()=>{Object.entries(originalColors).forEach(([name,value])=>{const field=document.querySelector('input[name="'+name+'"]');if(field){field.value=value;const hex=field.parentElement.querySelector('small');if(hex)hex.textContent=value;}});updateColorPreview();});</script></main></div></div></body></html>
